  "Apple’s first-launch dialog should identify MixBar as notarized software. Choose": { pl: "Okno pierwszego uruchomienia Apple powinno wskazywać MixBar jako oprogramowanie notaryzowane. Wybierz", de: "Apples Dialog beim ersten Start sollte MixBar als notarisiert ausweisen. Wähle", es: "El diálogo inicial de Apple debería identificar MixBar como software notarizado. Elige", fr: "La boîte de dialogue Apple doit identifier MixBar comme logiciel notarié. Choisissez" },
  "Start music or video in any app.": { pl: "Uruchom muzykę lub film w dowolnej aplikacji.", de: "Starte Musik oder ein Video in einer App.", es: "Reproduce música o vídeo en cualquier app.", fr: "Lancez de la musique ou une vidéo dans une app." },
  "In the MixBar setup guide, choose": { pl: "W przewodniku konfiguracji MixBar wybierz", de: "Wähle in der MixBar-Einrichtung", es: "En la guía de MixBar, elige", fr: "Dans le guide MixBar, choisissez" },
