  "complete installation guide": { pl: "pełną instrukcję instalacji", de: "vollständige Installationsanleitung", es: "guía de instalación completa", fr: "guide d’installation complet" },
  "Need help?": { pl: "Potrzebujesz pomocy?", de: "Brauchst du Hilfe?", es: "¿Necesitas ayuda?", fr: "Besoin d’aide ?" },
