  "Tab volume": { pl: "Głośność karty", de: "Tab-Lautstärke", es: "Volumen de pestaña", fr: "Volume de l’onglet" },
  "How it works": { pl: "Jak to działa", de: "Funktionsweise", es: "Cómo funciona", fr: "Fonctionnement" },
